/* @lc app=leetcode id=2616 lang=kotlin */ class Solution { fun minimizeMax(nums: IntArray, p: Int): Int = nums.sorted().let { a -> generateSequence(0 to 1_000_000_000) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { mid -> if (generateSequence(0 to 0) { (i, c) -> if (i >= a.size - 1) null else if (a[i + 1] - a[i] <= mid) i + 2 to c + 1 else i + 1 to c }.last().second >= p) lo to mid else mid + 1 to hi } }.last().first } }